namespace SchedulingShowcase;

// Original C# input shape retained. Index is metadata; current list order breaks ties.
public sealed record ProcessDefinition(
    int Index,
    string Name,
    int ReadyTime,
    int ExecutionTime,
    int? Deadline);

namespace SchedulingShowcase;

public interface ISchedulingStrategy
{
    string Id { get; }
    string Name { get; }
    ScheduleResult Schedule(IReadOnlyList<ProcessDefinition> processes, int quantum = 3);
}

namespace SchedulingShowcase;

public sealed class ShortestJobFirstStrategy : ISchedulingStrategy
{
    public string Id => "sjf";
    public string Name => "SJF (non-preemptive)";

    public ScheduleResult Schedule(IReadOnlyList<ProcessDefinition> processes, int quantum = 3)
    {
        var working = ProcessStateFactory.CreateWorkingSet(processes, quantum);
        var timeline = new TimelineBuilder();
        var time = 0;
        var finished = 0;

        while (finished < working.Count)
        {
            var ready = working.Where(process => !process.IsFinished && process.Definition.ReadyTime <= time).ToList();
            if (ready.Count == 0)
            {
                timeline.IdleUntil(working.Where(process => !process.IsFinished)
                    .Min(process => process.Definition.ReadyTime), ref time);
                continue;
            }
            var next = ready.OrderBy(process => process.Definition.ExecutionTime)
                .ThenBy(process => process.Definition.ReadyTime).ThenBy(process => process.Rank).First();
            timeline.Run(next, next.Remaining, ref time);
            finished++;
        }
        return ScheduleResultFactory.Create(Id, quantum, working, timeline, time);
    }
}

namespace SchedulingShowcase;

internal sealed class PreemptiveStrategy(string id, string name, Func<ProcessState, int, double> priority)
    : ISchedulingStrategy
{
    private readonly Func<ProcessState, int, double> _priority = priority ?? throw new ArgumentNullException(nameof(priority));
    public string Id { get; } = id ?? throw new ArgumentNullException(nameof(id));
    public string Name { get; } = name ?? throw new ArgumentNullException(nameof(name));

    public ScheduleResult Schedule(IReadOnlyList<ProcessDefinition> processes, int quantum = 3)
    {
        var working = ProcessStateFactory.CreateWorkingSet(processes, quantum);
        var timeline = new TimelineBuilder();
        var time = 0;
        var finished = 0;

        while (finished < working.Count)
        {
            var ready = working.Where(process => !process.IsFinished && process.Definition.ReadyTime <= time).ToList();
            if (ready.Count == 0)
            {
                timeline.IdleUntil(working.Where(process => !process.IsFinished)
                    .Min(process => process.Definition.ReadyTime), ref time);
                continue;
            }
            var current = ready.OrderBy(process => _priority(process, time))
                .ThenBy(process => process.Definition.ReadyTime).ThenBy(process => process.Rank).First();
            timeline.Run(current, 1, ref time);
            if (current.IsFinished) finished++;
        }
        return ScheduleResultFactory.Create(Id, quantum, working, timeline, time);
    }
}

namespace SchedulingShowcase;

public sealed class RoundRobinStrategy : ISchedulingStrategy
{
    public string Id => "rr";
    public string Name => "Round Robin";

    public ScheduleResult Schedule(IReadOnlyList<ProcessDefinition> processes, int quantum = 3)
    {
        var working = ProcessStateFactory.CreateWorkingSet(processes, quantum);
        var timeline = new TimelineBuilder();
        var time = 0;
        var finished = 0;
        var queue = new Queue<ProcessState>();
        // Includes the running job until it finishes, preventing duplicate admission.
        var admitted = new HashSet<string>(StringComparer.Ordinal);

        void EnqueueReady()
        {
            foreach (var process in working.Where(process => !process.IsFinished &&
                         process.Definition.ReadyTime <= time && admitted.Add(process.Definition.Name)))
                queue.Enqueue(process);
        }

        EnqueueReady();
        while (finished < working.Count)
        {
            if (queue.Count == 0)
            {
                timeline.IdleUntil(working.Where(process => !process.IsFinished)
                    .Min(process => process.Definition.ReadyTime), ref time);
                EnqueueReady();
                continue;
            }
            var current = queue.Dequeue();
            var slice = Math.Min(quantum, current.Remaining);
            for (var step = 0; step < slice; step++)
            {
                timeline.Run(current, 1, ref time);
                // Boundary arrivals are admitted before the current job is requeued.
                EnqueueReady();
                if (!current.IsFinished) continue;
                finished++;
                admitted.Remove(current.Definition.Name);
                break;
            }
            if (!current.IsFinished) queue.Enqueue(current);
        }
        return ScheduleResultFactory.Create(Id, quantum, working, timeline, time);
    }
}

namespace SchedulingShowcase;

public sealed class ProcessState(ProcessDefinition definition, int rank)
{
    public ProcessDefinition Definition { get; } = definition ?? throw new ArgumentNullException(nameof(definition));
    public int Rank { get; } = rank;
    public int Remaining { get; internal set; } = definition.ExecutionTime;
    public int StartTime { get; internal set; } = -1;
    public int CompletionTime { get; internal set; } = -1;
    public bool IsFinished => Remaining == 0 && CompletionTime >= 0;
    public int TurnaroundTime => CompletionTime - Definition.ReadyTime;
    public int WaitingTime => TurnaroundTime - Definition.ExecutionTime;
    public int ResponseTime => StartTime - Definition.ReadyTime;
}
